'use strict';
const files={extensions:['dist/extensions.js','../extensions.js'],comparison:['FEATURE_COMPARISON.md','files/FEATURE_COMPARISON.md'],r:['dist/analysis.R','../analysis.R'],ij:['dist/review-image.ijm','../review-image.ijm'],readme:['README.md','files/README.md'],html:['dist/index.html','../index.html'],style:['dist/microbelog.css','../microbelog.css'],app:['dist/microbelog.js','../microbelog.js'],engine:['dist/engine.js','../engine.js'],prepare:['prepare_data.py','files/prepare_data.py'],server:['serve.py','files/serve.py'],checks:['check_engine.cjs','files/check_engine.cjs'],dataset:['DATA_README.md','files/DATA_README.md']};
let version=0;
async function showFile(key){const current=++version;const [name,url]=files[key];document.querySelector('#filename').textContent=name;document.querySelector('#raw').href=url;document.querySelector('#source').textContent='Loading source…';document.querySelectorAll('[data-file]').forEach(b=>b.classList.toggle('active',b.dataset.file===key));try{const response=await fetch(url);if(!response.ok)throw new Error('Could not load file');const code=await response.text();if(current===version)document.querySelector('#source').textContent=code;}catch(e){if(current===version)document.querySelector('#source').textContent=e.message;}}
document.querySelectorAll('[data-file]').forEach(button=>button.onclick=()=>showFile(button.dataset.file));showFile('readme');
